contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address receiver) public payable {
        require(receiver != address(this));

        // Advance the state to finish distribution so getTokens() must revert.
        c.finishDistribution(); if (__ESBMC_reverted()) return;

        bool blacklistedAfter = c.blacklist(receiver); if (__ESBMC_reverted()) return;

        bool reverted;
        c.getTokens(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Since distribution is finished, getTokens() must revert without changing
        // the blacklist status of any address.
        assert(c.blacklist(receiver) == blacklistedAfter && reverted);
    }
}

