    }

    function _run(address receiver) internal {
        vm.assume(receiver != address(this));
        try c.finishDistribution() {} catch { return; }
        bool blacklistedAfter;
        try c.blacklist(receiver) returns (bool __r) { blacklistedAfter = __r; } catch { return; }
        bool reverted;
        try c.getTokens() {
            reverted = false;
        } catch {
            reverted = true;
        }
